import{at as e,it as t,t as n,vt as r}from"./chunks/framework.B8HA7oqK.js";var i=JSON.parse(`{"title":"Runtime Environment and Script Loading","description":"","frontmatter":{},"headers":[],"relativePath":"en/development/lua/environment.md","filePath":"en/development/lua/environment.md","lastUpdated":1791683719000}`),a={name:`en/development/lua/environment.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="runtime-environment-and-script-loading" tabindex="-1">Runtime Environment and Script Loading <a class="header-anchor" href="#runtime-environment-and-script-loading" aria-label="Permalink to “Runtime Environment and Script Loading”">​</a></h1><h2 id="lua-environment" tabindex="-1">Lua Environment <a class="header-anchor" href="#lua-environment" aria-label="Permalink to “Lua Environment”">​</a></h2><p>Xray currently uses GopherLua, which supports Lua 5.1 syntax, Lua 5.2&#39;s <code>goto</code> statement, and its own <a href="https://github.com/yuin/gopher-lua#lua-api" target="_blank" rel="noreferrer"><code>channel</code></a>.</p><p>Xray loads Lua scripts according to the configuration file. The configuration location determines the script&#39;s purpose and the available Hooks. See the <a href="./#hook">Hook reference</a> for each entry point&#39;s Hooks and calling conventions.</p><h2 id="module-loading" tabindex="-1">Module Loading <a class="header-anchor" href="#module-loading" aria-label="Permalink to “Module Loading”">​</a></h2><p>API modules are organized by functionality and loaded with <code>require</code>:</p><div class="language-lua line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes dark-plus light-plus" style="--shiki-dark:#D4D4D4;--shiki-light:#000000;--shiki-dark-bg:#1E1E1E;--shiki-light-bg:#FFFFFF;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#569CD6;--shiki-light:#0000FF;">local</span><span style="--shiki-dark:#9CDCFE;--shiki-light:#001080;"> geodata</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;"> = </span><span style="--shiki-dark:#DCDCAA;--shiki-light:#795E26;">require</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">(</span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;">&quot;xray.geodata&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">)</span></span>
<span class="line"><span style="--shiki-dark:#569CD6;--shiki-light:#0000FF;">local</span><span style="--shiki-dark:#9CDCFE;--shiki-light:#001080;"> log</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;"> = </span><span style="--shiki-dark:#DCDCAA;--shiki-light:#795E26;">require</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">(</span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;">&quot;xray.log&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>See <a href="./#module-api">Module API</a> for the module list, and each API reference for function usage.</p><p>See <a href="./guide/lifecycle.html">Instances and Lifecycle</a> for when top-level initialization, such as loading Lua modules and creating objects, runs.</p><h2 id="script-file-paths" tabindex="-1">Script File Paths <a class="header-anchor" href="#script-file-paths" aria-label="Permalink to “Script File Paths”">​</a></h2><p>The <code>script</code> field in the configuration file specifies the path to a Lua script. An empty string or an omitted field disables the script; an absolute path locates the file directly.</p><p>Relative paths are searched in the following order. If a path does not exist, the search continues; if it exists but is not a regular file, an error is raised immediately:</p><ol><li>The directory specified by the <code>XRAY_LOCATION_CONFDIR</code> environment variable;</li><li>The directory specified by the <code>XRAY_LOCATION_CONFIG</code> environment variable;</li><li>The Xray process&#39;s current working directory;</li><li>The directory containing the Xray executable.</li></ol><p>See <a href="./../../config/env.html">Environment Variables</a> for these directory settings. Relative paths are not automatically resolved against the directory containing the configuration file.</p><p>For example, when the script path is <code>routing.lua</code>, Xray searches for the file in the order above. A Windows absolute path can be written as <code>C:/Xray/routing.lua</code>; if you use backslashes, escape them as required by your configuration format.</p>`,15)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};